import{_ as e,o as i,c as s,ah as a}from"./chunks/framework.DjU4PSOm.js";const k=JSON.parse('{"title":"NVMeV GC 기초 검증 실험","description":"","frontmatter":{},"headers":[{"level":2,"title":"목적","slug":"목적","link":"#목적","children":[]},{"level":2,"title":"설정 변천 과정","slug":"설정-변천-과정","link":"#설정-변천-과정","children":[]},{"level":2,"title":"최종 실험 세팅 (Raw Device 방식)","slug":"최종-실험-세팅-raw-device-방식","link":"#최종-실험-세팅-raw-device-방식","children":[]},{"level":2,"title":"결과","slug":"결과","link":"#결과","children":[]},{"level":2,"title":"결론 및 다음 계획","slug":"결론-및-다음-계획","link":"#결론-및-다음-계획","children":[]}],"relativePath":"computer/Research/URA/results/01 NVMeV GC 기초 검증 실험.md","filePath":"computer/Research/URA/results/01 NVMeV GC 기초 검증 실험.md"}'),d={name:"computer/Research/URA/results/01 NVMeV GC 기초 검증 실험.md"};function l(n,t,r,h,o,c){return i(),s("div",null,[...t[0]||(t[0]=[a(`<h1 id="nvmev-gc-기초-검증-실험" tabindex="-1">NVMeV GC 기초 검증 실험 <a class="header-anchor" href="#nvmev-gc-기초-검증-실험" aria-label="Permalink to &quot;NVMeV GC 기초 검증 실험&quot;">​</a></h1><h2 id="목적" tabindex="-1">목적 <a class="header-anchor" href="#목적" aria-label="Permalink to &quot;목적&quot;">​</a></h2><p>NVMeVirt(가상 NVMe SSD)에서 fio로 write 부하를 가해 Garbage Collection(GC)을 실제로 유발시키고, 이로 인한 성능 저하(latency 증가)를 로그 기반으로 정량 검증한다.</p><h2 id="설정-변천-과정" tabindex="-1">설정 변천 과정 <a class="header-anchor" href="#설정-변천-과정" aria-label="Permalink to &quot;설정 변천 과정&quot;">​</a></h2><table tabindex="0"><thead><tr><th>시도</th><th>방식</th><th>결과</th></tr></thead><tbody><tr><td>1차 (200M, memmap 32G)</td><td><code>--size=200M</code> (디스크의 0.7%)</td><td>GC 0건 — free line이 트리거 조건(≤2)까지 못 내려감</td></tr><tr><td>2차 (3G, memmap 4G로 축소)</td><td><code>--size=3G</code> (디스크의 88%)</td><td>GC 132,731건 발생 — 트리거 조건 충족</td></tr><tr><td>3차 (Raw Device 방식)</td><td><code>GLOBAL_WB_SIZE=MB(1)</code> 고정 + mount 없이 <code>/dev/nvme1n1</code> 직접 I/O</td><td>GC 18건 (2200M seq write 기준), 코드 계측 기반이라 신뢰도 높음</td></tr></tbody></table><p><strong>GC 트리거 조건</strong> (<code>conv_ftl.c</code>): <code>free_line_cnt &lt;= gc_thres_lines</code> (기본값 2) — 전체 line의 약 99.98%가 채워져야 발동하는 보수적 조건. 따라서 디스크를 충분히(80% 이상) 채우지 못하면 GC가 전혀 관찰되지 않음.</p><h2 id="최종-실험-세팅-raw-device-방식" tabindex="-1">최종 실험 세팅 (Raw Device 방식) <a class="header-anchor" href="#최종-실험-세팅-raw-device-방식" aria-label="Permalink to &quot;최종 실험 세팅 (Raw Device 방식)&quot;">​</a></h2><div class="language-c vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">c</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">NAND_CHANNELS </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, LUNS_PER_NAND_CH </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, PLNS_PER_LUN </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">GLOBAL_WB_SIZE </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> MB</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   // 채널/LUN 값과 무관하게 고정 → 초기 크래시(buffer_allocate) 원인 해소</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">MDTS </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 6</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                  // 버퍼가 충분히 커서 낮출 필요 없음</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">NAND_ERASE_LATENCY </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 3</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">500</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">0</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">00</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#B31D28;--shiki-light-font-style:italic;--shiki-dark:#FDAEB7;--shiki-dark-font-style:italic;">3.5ms</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><ul><li><code>insmod memmap_size=32G</code>, <strong>mount 없이</strong> <code>fio --filename=/dev/nvme1n1</code>로 raw device에 직접 I/O</li><li><code>conv_ftl.c</code>의 <code>do_gc()</code>에서 <code>gc_count = 0</code>(매번 리셋되던 버그)을 <code>gc_count++</code>로 수정</li></ul><h2 id="결과" tabindex="-1">결과 <a class="header-anchor" href="#결과" aria-label="Permalink to &quot;결과&quot;">​</a></h2><p><strong>precondition 후 (100% 순차 쓰기)</strong> → <strong>seq_gc_invoke (2200M 추가 순차 쓰기)</strong> 후 rmmod 시점 dmesg:</p><table tabindex="0"><thead><tr><th>항목</th><th>값</th></tr></thead><tbody><tr><td>tt_lines</td><td>8192</td></tr><tr><td>full_line_cnt</td><td>7655</td></tr><tr><td>free_line_cnt</td><td>3</td></tr><tr><td>write_credits</td><td>192</td></tr><tr><td>victim_line_cnt</td><td>532</td></tr><tr><td>gc_count</td><td>18</td></tr></tbody></table><ul><li><code>tt_lines</code>(8192), <code>full_line_cnt</code>(7655)가 사전 계산값과 거의 정확히 일치</li><li><code>free_line_cnt</code>가 임계값(2) 바로 근처(3)에서 종료 — GC가 정상적으로 임계 조건까지 작동</li><li>코드 레벨 <code>gc_count</code> 계측이 dmesg grep 방식보다 신뢰도 높음을 확인</li></ul><p><strong>3G 실험 통계 (2차 시도, GC 132,731건 발생 구간)</strong></p><table tabindex="0"><thead><tr><th>항목</th><th>값</th></tr></thead><tbody><tr><td>평균 latency</td><td>66,220 ns</td></tr><tr><td>최대 latency</td><td>50,422,124 ns (50.4ms)</td></tr><tr><td>p50 / p99</td><td>58,624 ns / 288,768 ns</td></tr><tr><td>평균 IOPS</td><td>14,557</td></tr></tbody></table><p>Latency/IOPS는 약 50~55초 주기의 톱니(sawtooth) 패턴을 보임 — fio가 지정한 범위를 한 바퀴 돌 때마다 그 구간 전체가 재사용되며 대량의 invalid 페이지가 발생 → GC가 몰아서 처리(버스트) → 소강 → 다음 바퀴에서 반복되는 것으로 해석.</p><p><strong>GC 간격의 규칙성</strong>: write credit 체크 주기(<code>bs=256KiB</code> 기준 16개 요청마다)는 threshold 값과 무관하게 항상 고정. threshold는 &quot;체크 주기&quot;가 아니라 &quot;그 체크 시점마다 실제로 GC가 실행되는 비율&quot;을 바꾼다 — threshold를 높이면 동일한 16개 간격 패턴이 초반부터 쉼 없이 반복되는 형태로 나타남.</p><h2 id="결론-및-다음-계획" tabindex="-1">결론 및 다음 계획 <a class="header-anchor" href="#결론-및-다음-계획" aria-label="Permalink to &quot;결론 및 다음 계획&quot;">​</a></h2><ol><li>채널/LUN/파티션은 원래 스펙 유지 + <code>GLOBAL_WB_SIZE</code> 고정 + <code>memmap_size</code>로 총 용량 조절 = 크래시 없이 GC 유발 가능한 안정적 조합</li><li>GC 트리거는 보수적 조건(free line ≤ 2)이라, 디스크를 충분히 채워야 관찰 가능</li><li>dmesg 커널 로그와 fio 시계열 데이터를 함께 확보해야 GC-성능저하 인과관계를 로그 기반으로 검증 가능</li></ol><p><strong>다음 심화 실험 후보</strong></p><table tabindex="0"><thead><tr><th>#</th><th>아이디어</th><th>재빌드 필요</th></tr></thead><tbody><tr><td>1</td><td>threshold를 높여 precondition 중에도 GC 유발</td><td>필요</td></tr><tr><td>2</td><td>seq_gc_invoke의 <code>--size</code> 확대로 GC 여러 번 유발</td><td>불필요</td></tr><tr><td>3</td><td>2번 + threshold 상향 조합</td><td>필요</td></tr><tr><td>4</td><td>seq_gc_invoke를 랜덤 쓰기로 전환 (순차 vs 랜덤 GC 비용 비교)</td><td>불필요 (<code>--rw=randwrite</code>)</td></tr></tbody></table>`,21)])])}const _=e(d,[["render",l]]);export{k as __pageData,_ as default};
